/**
 * CarDBHelper module supports different functions to update mongoDB
 * database using mongoose.
 * It has the following uses :-
 * - find car using VIN number.
 * - find all cars matching the filter - it can be new car
 * or certified car or with max price range.
 * - upsert car (insert a car) and provide establish one-to-many
 * relationship with Brand model.
 * - delete car by marking the flag isDeleted to true, this maintains
 * the car in the database but won't be shown when user searches for all
 * the cars.
 *
 */
import {Car} from '../models/Cars.js';
import * as util from "../util.js"
import {Brand} from "../models/index.js";

