export async function deleteCar(vinNumber){
    let filter =  {vinNumber: vinNumber}

    let update = {
            $set: {
                isDeleted: true
            }
        }

        let deletedCar = await Car.findOneAndUpdate(filter, update,
        {
            new: true,
            upsert: true
        })

    console.log("CarDBHelper: Deleted Car",deletedCar)
    return deletedCar
}